import{_ as e,d as a,e as r,y as i}from"./chunks/framework.D7CAgLCq.js";const p=JSON.parse('{"title":"English lesson directory","description":"Find translations of all 421 Chinese reading lessons alongside the complete English theory.","frontmatter":{"title":"English lesson directory","description":"Find translations of all 421 Chinese reading lessons alongside the complete English theory."},"headers":[],"relativePath":"en/guide/selected-guides.md","filePath":"en/guide/selected-guides.md"}'),n={name:"en/guide/selected-guides.md"};function o(s,t,d,l,h,c){return a(),r("div",null,[...t[0]||(t[0]=[i('<h1 id="english-lesson-directory" tabindex="-1">English lesson directory <a class="header-anchor" href="#english-lesson-directory" aria-label="Permalink to &quot;English lesson directory&quot;">​</a></h1><p>The complete English theory contains <strong>397 numbered sections</strong>. All <strong>421 Chinese reading lessons</strong>, including front matter and part introductions, have English translations placed after the corresponding source passage. The translations include the full explanations, examples, case notes, counterexamples, questions and answers, and source records shown on the Chinese site.</p><p>Use the <a href="/xi-kari-skill/handbook/en/#lessons">searchable directory of all 421 lessons</a> to find a unit by number, title, or key point. The links below offer a few starting points through that complete collection. Original figures have English descriptions; downloadable historical research manuscripts and attachments remain in Chinese and retain their original dates.</p><div class="xk-table"><table><thead><tr><th>Source section</th><th>English guide</th></tr></thead><tbody><tr><td><a href="/xi-kari-skill/handbook/en/theory/part-02.html#section-2-1-1">§2.1.1</a></td><td>Domain evidence keeps its own standing</td></tr><tr><td><a href="/xi-kari-skill/handbook/en/theory/part-02.html#section-2-4-2">§2.4.2</a></td><td>Average effects do not automatically join into one chain</td></tr><tr><td><a href="/xi-kari-skill/handbook/en/theory/part-02.html#section-2-4-3">§2.4.3</a></td><td>A valid status and its consequences need different evidence</td></tr><tr><td><a href="/xi-kari-skill/handbook/en/theory/part-02.html#section-2-14">§2.14</a></td><td>Freeze a test without monopolizing the question</td></tr><tr><td><a href="/xi-kari-skill/handbook/en/theory/part-03.html#section-3-3">§3.3</a></td><td>Trace the return and the difference it causes</td></tr><tr><td><a href="/xi-kari-skill/handbook/en/theory/part-04.html#section-4-5">§4.5</a></td><td>History may act through a sufficient present carrier</td></tr><tr><td><a href="/xi-kari-skill/handbook/en/theory/part-04.html#section-4-6">§4.6</a></td><td>A useful prediction can fail under a new action</td></tr><tr><td><a href="/xi-kari-skill/handbook/en/theory/part-06.html#section-6-2-1">§6.2.1</a></td><td>Feedback delay changes the stability interval</td></tr><tr><td><a href="/xi-kari-skill/handbook/en/theory/part-06.html#section-6-3">§6.3</a></td><td>An update must be retained and used to support learning</td></tr><tr><td><a href="/xi-kari-skill/handbook/en/theory/part-06.html#section-6-6">§6.6</a></td><td>Recovery has several endpoints</td></tr><tr><td><a href="/xi-kari-skill/handbook/en/theory/part-06.html#section-6-10-1">§6.10.1</a></td><td>Formation, maintenance, recovery, and replication are different outcomes</td></tr><tr><td><a href="/xi-kari-skill/handbook/en/theory/part-07.html#section-7-2-4">§7.2.4</a></td><td>Uptake carriers are not automatically responsible parties</td></tr><tr><td><a href="/xi-kari-skill/handbook/en/theory/part-07.html#section-7-3-9">§7.3.9</a></td><td>Equal total hours can hide unequal usable time</td></tr><tr><td><a href="/xi-kari-skill/handbook/en/theory/part-07.html#section-7-6-1">§7.6.1</a></td><td>Allocation can shape the capability used to justify later allocation</td></tr><tr><td><a href="/xi-kari-skill/handbook/en/theory/part-08.html#section-8-5-2">§8.5.2</a></td><td>Orderly exit requires more than declaring closure</td></tr><tr><td><a href="/xi-kari-skill/handbook/en/theory/part-12.html#section-12-6">§12.6</a></td><td>A warning, a response, and an outcome need separate evaluation</td></tr><tr><td><a href="/xi-kari-skill/handbook/en/theory/part-14.html#section-14-4-1">§14.4.1</a></td><td>Trace affected positions proportionately without shrinking protection</td></tr><tr><td><a href="/xi-kari-skill/handbook/en/theory/part-14.html#section-14-5">§14.5</a></td><td>Past consent does not close every later route of refusal</td></tr><tr><td><a href="/xi-kari-skill/handbook/en/theory/part-14.html#section-14-9-1">§14.9.1</a></td><td>A choice with losses still calls for a reasoned bounded judgment</td></tr><tr><td><a href="/xi-kari-skill/handbook/en/theory/part-16.html#section-16-23">§16.23</a></td><td>Human oversight needs a real path to change the action</td></tr><tr><td><a href="/xi-kari-skill/handbook/en/theory/part-16.html#section-16-24">§16.24</a></td><td>Replace a model when the comparison warrants it</td></tr><tr><td><a href="/xi-kari-skill/handbook/en/theory/appendix-c.html#section-c-7">§C.7</a></td><td>Sufficient information and correct execution are separate</td></tr><tr><td><a href="/xi-kari-skill/handbook/en/theory/appendix-c.html#section-c-9">§C.9</a></td><td>The right extra variable depends on the task</td></tr><tr><td><a href="/xi-kari-skill/handbook/en/theory/appendix-c.html#section-c-12">§C.12</a></td><td>Three forms of composition need three different checks</td></tr></tbody></table></div><p>For another way in, browse the fourteen <a href="/xi-kari-skill/handbook/en/concepts/">concept pages</a> or the eight <a href="/xi-kari-skill/handbook/en/cases/">case pages</a>. The case collection includes seven source-based accounts and one thematic guide to an explicitly identified older Chinese report. A guide’s source references locate the English reading edition; the <a href="/xi-kari-skill/handbook/en/downloads.html">Chinese original</a> remains authoritative.</p>',5)])])}const f=e(n,[["render",o]]);export{p as __pageData,f as default};
